const duePlansToRemind = `-- name: DuePlansToRemind :many
SELECT p.id AS plan_id, p.task, p.equipment_id, e.title, e.owner_org_id
FROM maintenance_plans p
JOIN equipment e ON e.id = p.equipment_id AND e.deleted_at IS NULL
WHERE p.is_active
  AND (p.last_reminded_at IS NULL OR p.last_reminded_at < $1::timestamptz)
  AND ((p.every_days IS NOT NULL AND COALESCE(p.last_done_at, p.created_at) + make_interval(days => p.every_days) <= now())
    OR (p.every_hours IS NOT NULL AND e.current_hmr >= COALESCE(p.last_done_hmr, 0) + p.every_hours))
LIMIT 500
`

type DuePlansToRemindRow struct {
	PlanID      uuid.UUID `json:"plan_id"`
	Task        string    `json:"task"`
	EquipmentID uuid.UUID `json:"equipment_id"`
	Title       string    `json:"title"`
	OwnerOrgID  uuid.UUID `json:"owner_org_id"`
}

// Due plans not reminded in the last week (calendar or hour meter).
func (q *Queries) DuePlansToRemind(ctx context.Context, remindBefore time.Time) ([]DuePlansToRemindRow, error) {
	rows, err := q.db.Query(ctx, duePlansToRemind, remindBefore)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []DuePlansToRemindRow{}
	for rows.Next() {
		var i DuePlansToRemindRow
		if err := rows.Scan(
			&i.PlanID,
			&i.Task,
			&i.EquipmentID,
			&i.Title,
			&i.OwnerOrgID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

